<section class="card"><h2>Monthly Payslip · <?=access_h($statement['period'])?></h2><?php if(!empty($statement['statement_id'])):?><p>Issued Statement #<?=(int)$statement['statement_id']?></p><?php endif;if(!empty($statement['historical_version'])):?><p>Historical issued version. Later issued statements are available below.</p><?php endif;if(!empty($statement['pending_revision'])):?><p>A revised statement is awaiting review. The issued figures below are retained.</p><?php endif;if($statementVersions):?><nav class="payroll-row" aria-label="Issued Payslip Versions"><?php foreach($statementVersions as $issued):?><a class="payroll-button" href="<?=access_h(p_url(['page'=>'statement','id'=>$id,'statement_id'=>$issued['id']]))?>#payroll-action">Statement #<?=(int)$issued['id']?> · <?=access_h(display_date($issued['published_at']))?></a><?php endforeach?></nav><?php endif?><p><?=access_h($statement['staff_name'].' · '.$statement['staff_no'])?></p><?php if($owner&&!empty($statement['recovery_due'])):?><p>Private Recovery Due <?=access_h(p_money($statement['recovery_due']))?> · Revised publication waits for resolution.</p><?php endif?><?php if($owner):?><p>Owner Preview<?=$statement['due']>0?' · Employee Settlement Incomplete':''?></p><?php endif?><dl class="payroll-totals"><?php foreach(['base'=>'Base Salary','allowance'=>'Allowances','overtime'=>'Overtime','gross'=>'Gross Pay','deductions'=>'Deductions','net'=>'Employee Net Pay','paid'=>'Recorded Payments','due'=>'Employee Balance'] as $n=>$label):?><div><dt><?=access_h($label)?></dt><dd><?=access_h(p_money($statement[$n]))?></dd></div><?php endforeach?></dl><?php if($statement['adjustment']):?><p><?=access_h($statement['adjustment'])?></p><?php endif?><p><?=access_h($statement['wallet'])?> · Salary Revision #<?=(int)$statement['revision']?></p><p><?=!empty($statement['corrections'])?'Original Approval By':'Approved by'?> <?=access_h($statement['approved_by'].' · '.display_date($statement['approved_at']))?> UTC</p><h3>Recorded Payments</h3><?php foreach($statement['payments'] as $payment):?><p><?=access_h(p_money($payment['amount']).' · '.$payment['reference'].' · '.display_date($payment['paid_at']))?> UTC · <?=access_h($payment['recorded_by'])?></p><?php if(isset($payment['original_amount'])&&$payment['original_amount']!==$payment['amount']):?><p>Original Recorded Transfer <?=access_h(p_money($payment['original_amount']))?> · Linked Recording Adjustment <?=access_h(p_money($payment['amount']-$payment['original_amount']))?></p><?php endif;endforeach;if(!$statement['payments']):?><p>No employee payment was required for this zero-net statement.</p><?php endif?><?php if(!empty($statement['corrections'])):?><h3>Linked Payroll Revisions</h3><?php foreach($statement['corrections'] as $revision):?><p>Revision #<?=(int)$revision['id']?> · <?=access_h(display_date($revision['recorded_at']))?> UTC · Recorded By <?=access_h($revision['recorded_by'])?> · <?=access_h($revision['employee_note']?:'Payroll figures reviewed and revised.')?></p><?php endforeach;endif?><p>Employee settlement does not confirm payment of withheld deductions or employer remittances.</p></section>
